@app.patch("/admin/audit/{entry_id}", response_model=AuditEntryResponse, dependencies=[Depends(require_admin)])
def amend_audit_entry(entry_id: int, body: dict, session: Session = Depends(db.get_db)):
    from ledgerlite.models import AuditEntry
    entry = session.get(AuditEntry, entry_id)
    if entry is None:
        raise HTTPException(status_code=404, detail="Audit entry not found")
    entry.detail = body.get("detail", entry.detail)
    session.commit()
    session.refresh(entry)
    return entry


